int minCoins(const vector<int>& coins, int amount) {   // dynamika — działa dla dowolnych nominałów
    vector<int> dp(amount + 1, INT_MAX);
    dp[0] = 0;
    for (int x = 1; x <= amount; x++)
        for (int c : coins)
            if (c <= x && dp[x - c] != INT_MAX) dp[x] = min(dp[x], dp[x - c] + 1);
    return dp[amount] == INT_MAX ? -1 : dp[amount];
}

struct Task { long long t, w; };   // czas trwania, waga
bool before(const Task& a, const Task& b) { return a.t * b.w < b.t * a.w; }   // reguła Smitha
long long weightedCompletion(vector<Task> v) {
    sort(v.begin(), v.end(), before);
    long long time = 0, total = 0;
    for (auto& x : v) { time += x.t; total += x.w * time; }
    return total;
}

