vector<long long> a, tmp;

// Sortuje a[lo..hi) i zwraca liczbę inwersji w tym fragmencie.
long long mergeSort(int lo, int hi) {
    if (hi - lo <= 1) return 0;
    int mid = (lo + hi) / 2;
    long long inv = mergeSort(lo, mid) + mergeSort(mid, hi);
    int i = lo, j = mid, k = lo;
    while (i < mid && j < hi) {
        if (a[i] <= a[j]) tmp[k++] = a[i++];   // <= : równe elementy nie są inwersją
        else {
            inv += mid - i;                    // a[i..mid) są większe od a[j]
            tmp[k++] = a[j++];
        }
    }
    while (i < mid) tmp[k++] = a[i++];
    while (j < hi) tmp[k++] = a[j++];
    for (int p = lo; p < hi; p++) a[p] = tmp[p];
    return inv;
}

