#include <bits/stdc++.h>
using namespace std;

struct DSU {
    vector<int> parent, size_;
    DSU(int n) : parent(n), size_(n, 1) { iota(parent.begin(), parent.end(), 0); }
    int find(int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); }
    void unite(int a, int b) {
        a = find(a), b = find(b);
        if (a == b) return;
        if (size_[a] < size_[b]) swap(a, b);
        parent[b] = a;
        size_[a] += size_[b];
    }
};

// Zapytanie (u, v, w): czy u i v są połączone, używając tylko krawędzi o wadze <= w?
int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, m, q;
    cin >> n >> m >> q;
    vector<array<int, 3>> edges(m);                 // {waga, a, b}
    for (auto& [w, a, b] : edges) cin >> a >> b >> w;
    vector<array<int, 4>> queries(q);               // {w, u, v, indeks}
    for (int i = 0; i < q; i++) {
        auto& [w, u, v, idx] = queries[i];
        cin >> u >> v >> w;
        idx = i;
    }
    sort(edges.begin(), edges.end());
    sort(queries.begin(), queries.end());
    DSU dsu(n + 1);
    vector<bool> answer(q);
    int e = 0;
    for (auto [w, u, v, idx] : queries) {
        while (e < m && edges[e][0] <= w) {         // dodaj wszystkie krawędzie <= w
            dsu.unite(edges[e][1], edges[e][2]);
            e++;
        }
        answer[idx] = dsu.find(u) == dsu.find(v);
    }
    for (bool ok : answer) cout << (ok ? "TAK" : "NIE") << '\n';
}

