// operacje: {typ, a, b}; typ 0 = usuń krawędź (a, b), typ 1 = zapytanie czy a i b połączone.
// initialEdges = krawędzie grafu na początku. Zwraca odpowiedzi w kolejności zapytań.
vector<bool> reverseProcess(int n, const vector<pair<int, int>>& initialEdges, const vector<array<int, 3>>& ops) {
    vector<int> parent(n);
    iota(parent.begin(), parent.end(), 0);
    function<int(int)> find = [&](int x) { return parent[x] == x ? x : parent[x] = find(parent[x]); };
    auto unite = [&](int a, int b) { parent[find(a)] = find(b); };
    set<pair<int, int>> removed;
    for (auto& [t, a, b] : ops) if (t == 0) removed.insert({min(a, b), max(a, b)});
    for (auto [a, b] : initialEdges) if (!removed.count({min(a, b), max(a, b)})) unite(a, b);
    vector<bool> ans;
    for (int i = (int)ops.size() - 1; i >= 0; i--) {
        auto [t, a, b] = ops[i];
        if (t == 0) unite(a, b);                       // usunięcie wstecz = dodanie
        else ans.push_back(find(a) == find(b));
    }
    reverse(ans.begin(), ans.end());
    return ans;
}

