pair<long long, long long> floydCycle(long long x0, const function<long long(long long)>& f) {   // {mu, lambda}
    long long slow = f(x0), fast = f(f(x0));
    while (slow != fast) { slow = f(slow); fast = f(f(fast)); }
    long long mu = 0;
    slow = x0;
    while (slow != fast) { slow = f(slow); fast = f(fast); mu++; }
    long long lambda = 1;
    fast = f(slow);
    while (slow != fast) { fast = f(fast); lambda++; }
    return {mu, lambda};
}

