#include <bits/stdc++.h>
using namespace std;

struct Fenwick {
    int n;
    vector<long long> t;
    Fenwick(int n) : n(n), t(n + 1, 0) {}
    void add(int i, long long v) { for (; i <= n; i += i & -i) t[i] += v; }
    long long sum(int i) const { long long s = 0; for (; i > 0; i -= i & -i) s += t[i]; return s; }
    long long sum(int l, int r) const { return sum(r) - sum(l - 1); }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n, q;
    cin >> n >> q;
    vector<long long> value(n + 1);
    for (int v = 1; v <= n; v++) cin >> value[v];
    vector<vector<int>> adj(n + 1);
    for (int i = 0; i < n - 1; i++) {
        int a, b;
        cin >> a >> b;
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    // Iteracyjny DFS od korzenia 1: tin = numer przy wejściu, tout = ostatni numer w poddrzewie.
    vector<int> tin(n + 1), tout(n + 1), parent(n + 1, 0), nextChild(n + 1, 0);
    int timer = 0;
    vector<int> st = {1};
    tin[1] = ++timer;
    while (!st.empty()) {
        int v = st.back();
        if (nextChild[v] < (int)adj[v].size()) {
            int u = adj[v][nextChild[v]++];
            if (u == parent[v]) continue;
            parent[u] = v;
            tin[u] = ++timer;
            st.push_back(u);
        } else {
            tout[v] = timer;
            st.pop_back();
        }
    }
    Fenwick fw(n);
    for (int v = 1; v <= n; v++) fw.add(tin[v], value[v]);
    while (q--) {
        int type, v;
        cin >> type >> v;
        if (type == 1) {                    // 1 v x: wartość v := x
            long long x;
            cin >> x;
            fw.add(tin[v], x - value[v]);
            value[v] = x;
        } else {                            // 2 v: suma w poddrzewie v
            cout << fw.sum(tin[v], tout[v]) << '\n';
        }
    }
}

