// g[mask] = suma f[s] po wszystkich podmaskach s maski mask — dwa sposoby.
int main() {
    int n;
    cin >> n;
    int full = 1 << n;
    vector<long long> f(full);
    for (auto& x : f) cin >> x;

    // 1) iterowanie po podmaskach: łącznie O(3^n)
    vector<long long> g1(full, 0);
    for (int mask = 0; mask < full; mask++) {
        for (int s = mask; s > 0; s = (s - 1) & mask) g1[mask] += f[s];
        g1[mask] += f[0];                        // pusta podmaska
    }

    // 2) SOS DP (sum over subsets): O(n * 2^n)
    vector<long long> g2(f);
    for (int bit = 0; bit < n; bit++)
        for (int mask = 0; mask < full; mask++)
            if (mask & (1 << bit)) g2[mask] += g2[mask ^ (1 << bit)];

    for (int i = 0; i < full; i++) cout << g1[i] << " \n"[i == full - 1];
    for (int i = 0; i < full; i++) cout << g2[i] << " \n"[i == full - 1];
}

